def find_weight_band(bands, weight_kg):
    lo, hi, found = 0, len(bands) - 1, -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if bands[mid] >= weight_kg:
            found = mid
            hi = mid - 1
        else:
            lo = mid + 1
    return found

from decimal import Decimal, ROUND_HALF_UP

def dose_to_ml(dose_mg, mg_per_ml):
    if mg_per_ml <= 0:
        raise ValueError('concentration must be positive')
    ml = Decimal(str(dose_mg)) / Decimal(str(mg_per_ml))
    return float(ml.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))

